    public function fetch_time($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_time(...))($params);
    }

    private function do_fetch_time($params = array()) {
        /**
         * fetches the current integer timestamp in milliseconds from the exchange server
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int} the current integer timestamp in milliseconds from the exchange server
         */
        $response = Async\await($this->publicGetInfoTime($params));
        //
        //     { "time": 1788524530209 }
        //
        return $this->safe_integer($response, 'time');
    }

    public function fetch_status($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_status(...))($params);
    }

    private function do_fetch_status($params = array()) {
        /**
         * the latest known information on the availability of the exchange api
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=exchange-status-structure status structure~
         */
        $response = Async\await($this->publicGetInfoExchange($params));
        //
        //     {
        //         "name": "Polymarket",
        //         "version": "1",
        //         "chain_id": 137,
        //         "contract": "0xDCa4af75705dbB50f62437045afF9921947917d2",
        //         "cancel_only": false,
        //         "engine_version": "0.0.69"
        //     }
        //
        $cancelOnly = $this->safe_bool($response, 'cancel_only', false);
        return array(
            'status' => ($cancelOnly) ? 'maintenance' : 'ok',
            'updated' => null,
            'eta' => null,
            'url' => null,
            'info' => $response,
        );
    }

    public function fetch_currencies($params = array()): PromiseInterface {
