    private function do_fetch_currencies($params = array()) {
        /**
         * fetches all available currencies on an exchange - every $instrument base, the usd quote and the collateral $asset
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an associative dictionary of currencies
         */
        $promises = array(
            $this->publicGetInfoInstruments($params),
            $this->publicGetInfoAssets($params),
        );
        $responses = Async\await(Promise\all($promises));
        $instruments = $this->safe_list($responses, 0, array());
        $assets = $this->safe_list($responses, 1, array());
        $result = array();
        for ($i = 0; $i < count($instruments); $i++) {
            $instrument = $instruments[$i];
            $baseId = $this->safe_string($instrument, 'base_asset');
            if ($baseId === null) {
                continue;
            }
            $code = $this->safe_currency_code($baseId);
            if (!(is_array($result) && array_key_exists($code ?? '', $result))) {
                // the venue tags each underlying with a category - only the
                // crypto ones are unified as crypto, equities, commodities and
                // indices map onto the other currency type
                $category = $this->safe_string($instrument, 'category');
                $currencyType = ($category === 'crypto') ? 'crypto' : 'other';
                $result[$code] = $this->safe_currency_structure(array(
                    'id' => $baseId,
                    'code' => $code,
                    'name' => $baseId,
                    'info' => $instrument,
                    'active' => true,
                    'deposit' => false,
                    'withdraw' => false,
                    'fee' => null,
                    'precision' => $this->parse_number($this->parse_precision($this->safe_string($instrument, 'quantity_decimals'))),
                    'type' => $currencyType,
                    'networks' => array(),
                ));
            }
        }
        // every instrument quotes using usd
        $result['USD'] = $this->safe_currency_structure(array(
            'id' => 'USD',
            'code' => 'USD',
            'name' => 'USD',
            'info' => array(),
            'active' => true,
            'deposit' => false,
            'withdraw' => false,
            'fee' => null,
            'precision' => $this->parse_number('0.01'),
            'type' => 'fiat',
            'networks' => array(),
        ));
        for ($i = 0; $i < count($assets); $i++) {
            $asset = $assets[$i];
            $currencyId = $this->safe_string($asset, 'asset');
            if ($currencyId === null) {
                continue;
            }
            $code = $this->safe_currency_code($currencyId);
            $result[$code] = $this->safe_currency_structure(array(
                'id' => $currencyId,
                'code' => $code,
                'name' => $currencyId,
                'info' => $asset,
                'active' => true,
                'deposit' => true,
                'withdraw' => true,
                'fee' => $this->safe_number($asset, 'withdrawal_fee'),
                'precision' => $this->parse_number($this->parse_precision($this->safe_string($asset, 'decimals'))),
                'type' => 'crypto',
                'networks' => array(),
            ));
        }
        return $result;
    }

    public function fetch_markets($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_markets(...))($params);
    }

    private function do_fetch_markets($params = array()) {
        /**
         * retrieves data on all markets for polymarket perps
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing market data
         */
        $response = Async\await($this->publicGetInfoInstruments($params));
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "instrument_type": "perpetual",
        //             "category": "index",
        //             "isolated_only": false,
        //             "symbol": "SP500-USD",
        //             "base_asset": "SP500",
        //             "quote_asset": "pUSD",
        //             "funding_interval": "1h",
        //             "quantity_decimals": 5,
        //             "price_decimals": 1,
        //             "price_bounds": "0.05",
        //             "liquidation_fee": "0.005",
        //             "max_order_count": 200,
        //             "min_notional": "10",
        //             "max_market_notional": "1000000",
        //             "max_limit_notional": "5000000",
        //             "max_leverage": 20,
        //             "risk_tiers": [ { "lower_bound": "0", "max_leverage": 20 } ],
        //             "ui_live_time": 1785542400000
        //         }
        //     ]
        //
        return $this->parse_markets($response);
    }

    public function parse_market(array $market): array {
        $numericId = $this->safe_string($market, 'instrument_id');
        $venueSymbol = $this->safe_string($market, 'symbol');
        $baseId = $this->safe_string($market, 'base_asset');
        // prices are denominated using USD while pUSD is the 1:1 collateral and settlement token
        $settleId = $this->safe_string($market, 'quote_asset');
        $parts = explode('-', $venueSymbol);
        $quoteId = $this->safe_string($parts, 1, 'USD');
        $base = $this->safe_currency_code($baseId);
        $quote = $this->safe_currency_code($quoteId);
        $settle = $this->safe_currency_code($settleId);
        $crossAllowed = !($this->safe_bool($market, 'isolated_only', false));
        return $this->safe_market_structure(array(
            'id' => $numericId,
            'symbol' => $base . '/' . $quote . ':' . $settle,
            'base' => $base,
            'quote' => $quote,
            'settle' => $settle,
            'baseId' => $baseId,
            'quoteId' => $quoteId,
            'settleId' => $settleId,
            'type' => 'swap',
            'spot' => false,
            'margin' => false,
            'swap' => true,
            'future' => false,
            'option' => false,
            // the venue lists tradable instruments only, an exchange wide
            // halt surfaces through fetchStatus via the cancel_only flag
            'active' => true,
            'contract' => true,
            'linear' => true,
            'inverse' => false,
            // tier-0 rates from GET /v1/info/fees, shared by every category
            'taker' => $this->parse_number('0.0004'),
            'maker' => $this->parse_number('0.000125'),
            'contractSize' => $this->parse_number('1'),
            'expiry' => null,
            'expiryDatetime' => null,
            'strike' => null,
            'optionType' => null,
            'marginModes' => array(
                'cross' => $crossAllowed,
                'isolated' => true,
            ),
            'precision' => array(
                'amount' => $this->parse_number($this->parse_precision($this->safe_string($market, 'quantity_decimals'))),
                'price' => $this->parse_number($this->parse_precision($this->safe_string($market, 'price_decimals'))),
            ),
            'limits' => array(
                'leverage' => array(
                    'min' => $this->parse_number('1'),
                    'max' => $this->safe_number($market, 'max_leverage'),
                ),
                'amount' => array(
                    'min' => null,
                    'max' => null,
                ),
                'price' => array(
                    'min' => null,
                    'max' => null,
                ),
                'cost' => array(
                    'min' => $this->safe_number($market, 'min_notional'),
                    'max' => $this->safe_number($market, 'max_limit_notional'),
                ),
            ),
            'created' => null,
            'info' => $market,
        ));
    }

    public function fetch_ticker(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ticker(...))($symbol, $params);
    }

    private function do_fetch_ticker(string $symbol, $params = array()) {
        /**
         * fetches a price $ticker, a statistical calculation with the information calculated over the past 24 hours for a specific $market, merging the $ticker, statistics and best bid and ask endpoints
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the $ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$ticker-structure $ticker structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $symbolResolved = $market['symbol'];
        // the tickers and statistics endpoints ignore the documented
        // instrument_id filter and always answer with every instrument, so
        // the single-market call reuses the bulk fetch and selects one row
        $tickers = Async\await($this->fetch_tickers(array( $symbolResolved ), $params));
        $ticker = $this->safe_dict($tickers, $symbolResolved);
        if ($ticker === null) {
            throw new BadSymbol($this->id . ' fetchTicker() could not find a ticker for ' . $symbolResolved);
        }
        return $ticker;
    }

    public function fetch_tickers(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_tickers(...))($symbols, $params);
    }

    private function do_fetch_tickers(?array $symbols = null, $params = array()) {
        /**
         * fetches price $tickers for multiple markets, statistical information calculated over the past 24 hours for each market, merging the ticker, $statistics and best bid and ask endpoints
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string[]} [$symbols] unified $symbols of the markets to fetch the ticker for, all market $tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=ticker-structure ticker structures~
         */
        Async\await($this->load_markets());
        $symbolsNormalized = $this->market_symbols($symbols);
        $promises = array(
            $this->publicGetInfoTickers($params),
            $this->publicGetInfoStatistics($params),
            $this->publicGetInfoBbo($params),
        );
        $responses = Async\await(Promise\all($promises));
        //
        // tickers
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "symbol": "SP500-USD",
        //             "index_price": "7713.1",
        //             "mark_price": "7715",
        //             "last_price": "7714",
        //             "mid_price": "7715",
        //             "open_interest": "1101.82729",
        //             "funding_rate": "0.00000625",
        //             "next_funding": 1788548400000,
        //             "timestamp": 1788546972857
        //         }
        //     ]
        //
        // statistics
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "symbol": "SP500-USD",
        //             "volume": "2087643.9565559996",
        //             "open_price": "7754.5",
        //             "klines": [ [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ] ]
        //         }
        //     ]
        //
        // bbo
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "bid_price": "7715",
        //             "bid_quantity": "22.63803",
        //             "ask_price": "7715.1",
        //             "ask_quantity": "0.95534",
        //             "timestamp": 1788546975038
        //         }
        //     ]
        //
        $merged = array();
        $statistics = $this->safe_list($responses, 1, array());
        for ($i = 0; $i < count($statistics); $i++) {
            $entry = $statistics[$i];
            $instrumentId = $this->safe_string($entry, 'instrument_id');
            // the 24 hourly kline rows are dropped from the merged payload to keep tickers light, candles are served by fetchOHLCV
            $merged[$instrumentId] = $this->omit($entry, 'klines');
        }
        $bbos = $this->safe_list($responses, 2, array());
        for ($i = 0; $i < count($bbos); $i++) {
            $entry = $bbos[$i];
            $instrumentId = $this->safe_string($entry, 'instrument_id');
            $previous = $this->safe_dict($merged, $instrumentId, array());
            // the tickers endpoint timestamp wins the merge below because most unified fields come from it - bbo rows carry a slightly newer sampling time
            $merged[$instrumentId] = $this->extend($previous, $entry);
        }
        $tickers = $this->safe_list($responses, 0, array());
        $result = array();
        for ($i = 0; $i < count($tickers); $i++) {
            $entry = $tickers[$i];
            $instrumentId = $this->safe_string($entry, 'instrument_id');
            $previous = $this->safe_dict($merged, $instrumentId, array());
            $result[] = $this->extend($previous, $entry);
        }
        return $this->parse_tickers($result, $symbolsNormalized);
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        //
        // merged row assembled by fetchTickers from the tickers, statistics and bbo endpoints
        //
        //     {
        //         "instrument_id": 1,
        //         "symbol": "SP500-USD",
        //         "volume": "2087643.9565559996",
        //         "open_price": "7754.5",
        //         "bid_price": "7715",
        //         "bid_quantity": "22.63803",
        //         "ask_price": "7715.1",
        //         "ask_quantity": "0.95534",
        //         "index_price": "7713.1",
        //         "mark_price": "7715",
        //         "last_price": "7714",
        //         "mid_price": "7715",
        //         "open_interest": "1101.82729",
        //         "funding_rate": "0.00000625",
        //         "next_funding": 1788548400000,
        //         "timestamp": 1788546972857
        //     }
        //
        $marketId = $this->safe_string($ticker, 'instrument_id');
        $marketResolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($ticker, 'timestamp');
        return $this->safe_ticker(array(
            'symbol' => $marketResolved['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => null,
            'low' => null,
            'bid' => $this->safe_string($ticker, 'bid_price'),
            'bidVolume' => $this->safe_string($ticker, 'bid_quantity'),
            'ask' => $this->safe_string($ticker, 'ask_price'),
            'askVolume' => $this->safe_string($ticker, 'ask_quantity'),
            'vwap' => null,
            'open' => $this->safe_string($ticker, 'open_price'),
            'close' => $this->safe_string($ticker, 'last_price'),
            'last' => $this->safe_string($ticker, 'last_price'),
            'previousClose' => null,
            'change' => null,
            'percentage' => null,
            'average' => null,
            'baseVolume' => null,
            // the statistics volume is denominated using pUSD, verified against the sum of hourly candle base volumes
            'quoteVolume' => $this->safe_string($ticker, 'volume'),
            'markPrice' => $this->safe_string($ticker, 'mark_price'),
            'indexPrice' => $this->safe_string($ticker, 'index_price'),
            'info' => $ticker,
        ), $marketResolved);
    }

