    private function do_fetch_bids_asks(?array $symbols = null, $params = array()) {
        /**
         * fetches the best bid and ask price and volume for multiple markets
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string[]} [$symbols] unified $symbols of the markets to fetch the bids and asks for, all markets are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=ticker-structure ticker structures~
         */
        Async\await($this->load_markets());
        $symbolsNormalized = $this->market_symbols($symbols);
        $response = Async\await($this->publicGetInfoBbo($params));
        //
        //     [
        //         {
        //             "instrument_id": 1,
        //             "bid_price": "7715",
        //             "bid_quantity": "22.63803",
        //             "ask_price": "7715.1",
        //             "ask_quantity": "0.95534",
