        return $this->parse_tickers($response, $symbolsNormalized);
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_book(...))($symbol, $limit, $params);
    }

    private function do_fetch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] the maximum amount of order book entries to return, must be one of 10, 100, 500 or 1000, the default is 100
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} A dictionary of ~@link https://docs.ccxt.com/#/?id=order-book-structure order book structures~ indexed by $market symbols
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'instrument_id' => $market['id'],
        );
        if ($limit !== null) {
            $request['depth'] = $limit;
        }
        $response = Async\await($this->publicGetInfoBook($this->extend($request, $params)));
        //
        //     {
        //         "instrument_id": 1,
        //         "bids": [ [ "7745.1", "0.319" ] ],
        //         "asks": [ [ "7745.2", "53.36141" ] ],
        //         "timestamp": 1788524545112,
        //         "sequence": 35631219797
        //     }
        //
        $timestamp = $this->safe_integer($response, 'timestamp');
        $orderbook = $this->parse_order_book($response, $market['symbol'], $timestamp);
        $orderbook['nonce'] = $this->safe_integer($response, 'sequence');
        return $orderbook;
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * get the list of the most recent trades for a particular $symbol
         *
         * @see https://docs.polymarket.com/perps/market-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum number of trades to fetch, the venue serves at most 100 per $request
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest trade to fetch
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/#/?id=public-trades trade structures~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'instrument_id' => $market['id'],
        );
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($params, 'until');
        $paramsOmitted = $params;
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $response = Async\await($this->publicGetInfoTrades($this->extend($request, $paramsOmitted)));
        //
        //     {
        //         "data": [
        //             {
        //                 "trade_id": 3738280849593744,
        //                 "instrument_id": 1,
        //                 "side": "long",
        //                 "price": "7714",
        //                 "quantity": "0.00136",
        //                 "timestamp": 1788546565789,
        //                 "hash": "0x"
        //             }
        //         ],
        //         "more": true
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_trades($data, $market, $since, $limit);
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        //
        //     {
        //         "trade_id": 3738280849593744,
        //         "instrument_id": 1,
        //         "side": "long",
        //         "price": "7714",
        //         "quantity": "0.00136",
        //         "timestamp": 1788546565789,
        //         "hash": "0x"
        //     }
        //
        $marketId = $this->safe_string_2($trade, 'instrument_id', 'iid');
        $marketResolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer_2($trade, 'timestamp', 'ts');
        $side = $this->safe_string_lower($trade, 'side');
        if ($side === 'long') {
            $side = 'buy';
        } elseif ($side === 'short') {
            $side = 'sell';
        }
        $isTaker = $this->safe_bool($trade, 'taker');
        $takerOrMaker = null;
        if ($isTaker !== null) {
            $takerOrMaker = ($isTaker) ? 'taker' : 'maker';
        }
        $feeCost = $this->safe_string($trade, 'fee');
        $fee = null;
        if ($feeCost !== null) {
            $feeCurrencyId = $this->safe_string_2($trade, 'fee_asset', 'fea');
            $fee = array(
                'cost' => $feeCost,
                'currency' => $this->safe_currency_code($feeCurrencyId),
            );
        }
        return $this->safe_trade(array(
            'id' => $this->safe_string_2($trade, 'trade_id', 'tid'),
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $marketResolved['symbol'],
            'order' => $this->safe_string_2($trade, 'order_id', 'oid'),
            'type' => null,
            'side' => $side,
            'takerOrMaker' => $takerOrMaker,
            'price' => $this->safe_string_2($trade, 'price', 'p'),
            'amount' => $this->safe_string_2($trade, 'quantity', 'qty'),
            'cost' => null,
            'fee' => $fee,
        ), $marketResolved);
    }

    public function fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($symbol, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $symbol, $timeframe = '1m', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick $data containing the open, high, low, and close price, and the volume of a $market
         *
         * @see https://docs.polymarket.com/perps/market-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch OHLCV $data for
         * @param {string} $timeframe the length of time each candle represents
         * @param {int} [$since] timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum amount of candles to fetch, the venue serves at most 1000 per $request
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest candle to fetch
         * @param {boolean} [$params->paginate] default false, when true will automatically $paginate by calling the endpoint multiple times
         * @return {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
         */
        Async\await($this->load_markets());
        $paginate = false;
        $paramsOmitted = $params;
        list($paginate, $paramsOmitted) = $this->handle_option_and_params($paramsOmitted, 'fetchOHLCV', 'paginate');
        if ($paginate) {
            return Async\await($this->fetch_paginated_call_deterministic('fetchOHLCV', $symbol, $since, $limit, $timeframe, $paramsOmitted, 1000));
        }
        $market = $this->market($symbol);
        $request = array(
            'instrument_id' => $market['id'],
            'interval' => $this->safe_string($this->timeframes, $timeframe, $timeframe),
        );
        $until = $this->safe_integer($paramsOmitted, 'until');
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $duration = $this->parse_timeframe($timeframe) * 1000;
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        } else {
            // the venue requires an explicit range start - the window covers
            // exactly the requested number of candle bins including the
            // current one, so the newest candle never falls off the range
            $end = ($until !== null) ? $until : $this->milliseconds();
            $requestedLimit = ($limit !== null) ? $limit : 100;
            $request['start_timestamp'] = $end - ($requestedLimit - 1) * $duration;
        }
        $response = Async\await($this->publicGetInfoKlines($this->extend($request, $paramsOmitted)));
        //
        //     {
        //         "data": [
        //             [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ]
        //         ],
        //         "more": false
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_ohlcvs($data, $market, $timeframe, $since, $limit);
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        //
        // rows carry the timestamp, open, high, low, close, base volume and the trade count
        //
        //     [ 1788458400000, "7754.5", "7754.5", "7751.4", "7751.4", "0.39184", 3 ]
        //
        return array(
            $this->safe_integer($ohlcv, 0),
            $this->safe_number($ohlcv, 1),
            $this->safe_number($ohlcv, 2),
            $this->safe_number($ohlcv, 3),
            $this->safe_number($ohlcv, 4),
            $this->safe_number($ohlcv, 5),
        );
    }

    public function fetch_funding_rate(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_funding_rate(...))($symbol, $params);
    }

    private function do_fetch_funding_rate(string $symbol, $params = array()) {
        /**
         * fetch the current funding rate
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=funding-rate-structure funding rate structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $symbolResolved = $market['symbol'];
        // the tickers endpoint ignores the documented instrument_id filter
        // and always answers with every instrument, so the single-market call
        // reuses the bulk fetch and selects the requested row
        $fundingRates = Async\await($this->fetch_funding_rates(array( $symbolResolved ), $params));
        $fundingRate = $this->safe_dict($fundingRates, $symbolResolved);
        if ($fundingRate === null) {
            throw new BadSymbol($this->id . ' fetchFundingRate() could not find the funding rate for ' . $symbolResolved);
        }
        return $fundingRate;
    }

    public function fetch_funding_rates(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_funding_rates(...))($symbols, $params);
    }

    private function do_fetch_funding_rates(?array $symbols = null, $params = array()) {
        /**
         * fetches the current funding rates for multiple markets
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string[]} [$symbols] unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=funding-rate-structure funding rate structures~
         */
        Async\await($this->load_markets());
        $symbolsNormalized = $this->market_symbols($symbols);
        $response = Async\await($this->publicGetInfoTickers($params));
        $result = $this->parse_funding_rates($response);
        return $this->index_by($this->filter_by_array($result, 'symbol', $symbolsNormalized, false), 'symbol');
    }

    public function parse_funding_rate(mixed $contract, ?array $market = null): array {
        //
        //     {
        //         "instrument_id": 1,
        //         "symbol": "SP500-USD",
        //         "index_price": "7713.1",
        //         "mark_price": "7715",
        //         "last_price": "7714",
        //         "mid_price": "7715",
        //         "open_interest": "1101.82729",
        //         "funding_rate": "0.00000625",
        //         "next_funding": 1788548400000,
        //         "timestamp": 1788546972857
        //     }
        //
        $marketId = $this->safe_string($contract, 'instrument_id');
        $marketResolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($contract, 'timestamp');
        $nextFundingTimestamp = $this->safe_integer($contract, 'next_funding');
        $interval = $this->safe_string($marketResolved['info'], 'funding_interval');
        return array(
            'info' => $contract,
            'symbol' => $marketResolved['symbol'],
            'markPrice' => $this->safe_number($contract, 'mark_price'),
            'indexPrice' => $this->safe_number($contract, 'index_price'),
            'interestRate' => null,
            'estimatedSettlePrice' => null,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'fundingRate' => $this->safe_number($contract, 'funding_rate'),
            'fundingTimestamp' => null,
            'fundingDatetime' => null,
            'nextFundingRate' => null,
            'nextFundingTimestamp' => $nextFundingTimestamp,
            'nextFundingDatetime' => $this->iso8601($nextFundingTimestamp),
            'previousFundingRate' => null,
            'previousFundingTimestamp' => null,
            'previousFundingDatetime' => null,
            'interval' => $interval,
        );
    }

    public function fetch_funding_rate_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_funding_rate_history(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_funding_rate_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical funding rate prices
         *
         * @see https://docs.polymarket.com/perps/market-$data
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the funding rate history for
         * @param {int} [$since] $timestamp in ms of the earliest funding rate to fetch
         * @param {int} [$limit] the maximum amount of funding rate structures to fetch, the venue serves at most 100 per $request
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] $timestamp in ms of the latest funding rate to fetch
         * @param {boolean} [$params->paginate] default false, when true will automatically $paginate by calling the endpoint multiple times
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=funding-rate-history-structure funding rate structures~
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' fetchFundingRateHistory() requires a symbol argument');
        }
        Async\await($this->load_markets());
        $paginate = false;
        $paramsOmitted = $params;
        list($paginate, $paramsOmitted) = $this->handle_option_and_params($paramsOmitted, 'fetchFundingRateHistory', 'paginate');
        if ($paginate) {
            return Async\await($this->fetch_paginated_call_deterministic('fetchFundingRateHistory', $symbol, $since, $limit, '1h', $paramsOmitted, 100));
        }
        $market = $this->market($symbol);
        $request = array(
            'instrument_id' => $market['id'],
        );
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($paramsOmitted, 'until');
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $response = Async\await($this->publicGetInfoFunding($this->extend($request, $paramsOmitted)));
        //
        //     {
        //         "data": [
        //             { "funding_rate": "0.00000625", "timestamp": 1788544800063 }
        //         ],
        //         "more": false
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $rates = array();
        for ($i = 0; $i < count($data); $i++) {
            $entry = $data[$i];
            $timestamp = $this->safe_integer($entry, 'timestamp');
            $rates[] = array(
                'info' => $entry,
                'symbol' => $market['symbol'],
                'fundingRate' => $this->safe_number($entry, 'funding_rate'),
                'timestamp' => $timestamp,
                'datetime' => $this->iso8601($timestamp),
            );
        }
        $sorted = $this->sort_by($rates, 'timestamp');
        return $this->filter_by_symbol_since_limit($sorted, $market['symbol'], $since, $limit);
    }

    public function fetch_open_interest(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_interest(...))($symbol, $params);
    }

    private function do_fetch_open_interest(string $symbol, $params = array()) {
        /**
         * retrieves the open interest of a contract trading pair
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=open-interest-structure open interest structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $symbolResolved = $market['symbol'];
        // the tickers endpoint ignores the documented instrument_id filter
        // and always answers with every instrument, so the single-market call
        // reuses the bulk fetch and selects the requested row
        $openInterests = Async\await($this->fetch_open_interests(array( $symbolResolved ), $params));
        $openInterest = $this->safe_dict($openInterests, $symbolResolved);
        if ($openInterest === null) {
            throw new BadSymbol($this->id . ' fetchOpenInterest() could not find the open interest for ' . $symbolResolved);
        }
        return $openInterest;
    }

    public function fetch_open_interests(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_interests(...))($symbols, $params);
    }

    private function do_fetch_open_interests(?array $symbols = null, $params = array()) {
        /**
         * retrieves the open interest of multiple contract trading pairs
         *
         * @see https://docs.polymarket.com/perps/market-data
         *
         * @param {string[]} [$symbols] unified market $symbols, all markets are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=open-interest-structure open interest structures~
         */
        Async\await($this->load_markets());
        $symbolsNormalized = $this->market_symbols($symbols);
        $response = Async\await($this->publicGetInfoTickers($params));
        $result = $this->parse_open_interests($response);
        return $this->index_by($this->filter_by_array($result, 'symbol', $symbolsNormalized, false), 'symbol');
    }

    public function parse_open_interest(?array $interest, ?array $market = null) {
        //
        //     {
        //         "instrument_id": 1,
        //         "symbol": "SP500-USD",
        //         "index_price": "7713.1",
        //         "mark_price": "7715",
        //         "last_price": "7714",
        //         "mid_price": "7715",
        //         "open_interest": "1101.82729",
        //         "funding_rate": "0.00000625",
        //         "next_funding": 1788548400000,
        //         "timestamp": 1788546972857
        //     }
        //
        $marketId = $this->safe_string($interest, 'instrument_id');
        $marketResolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer($interest, 'timestamp');
        return $this->safe_open_interest(array(
            'symbol' => $marketResolved['symbol'],
            'openInterestAmount' => $this->safe_string($interest, 'open_interest'),
            'openInterestValue' => null,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'info' => $interest,
        ), $marketResolved);
    }

    public function fetch_trading_fees($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trading_fees(...))($params);
    }

    private function do_fetch_trading_fees($params = array()) {
        /**
         * fetches the default trading fees for multiple markets
         *
         * @see https://docs.polymarket.com/perps/learn-about-trading/fees
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of ~@link https://docs.ccxt.com/#/?id=fee-structure fee structures~ indexed by $market symbols
         */
        Async\await($this->load_markets());
        $response = Async\await($this->publicGetInfoFees($params));
        //
        //     {
        //         "fee_schedule": [
        //             {
        //                 "instrument_type": "perpetual",
        //                 "category": "equity",
        //                 "taker_fee_rate": "0.0004",
        //                 "maker_fee_rate": "0.000125",
        //                 "tiers": [ { "min_volume_30d": "0", "taker_fee_rate": "0.0004", "maker_fee_rate": "0.000125" } ]
        //             }
        //         ]
        //     }
        //
        $schedule = $this->safe_list($response, 'fee_schedule', array());
        $byCategory = array();
        for ($i = 0; $i < count($schedule); $i++) {
            $entry = $schedule[$i];
            $category = $this->safe_string($entry, 'category');
            $byCategory[$category] = $entry;
        }
        $fallback = $this->safe_dict($schedule, 0, array());
        $result = array();
        for ($i = 0; $i < count($this->symbols); $i++) {
            $symbol = $this->safe_string($this->symbols, $i, '');
            $market = $this->market($symbol);
            $category = $this->safe_string($market['info'], 'category');
            $entry = $this->safe_dict($byCategory, $category, $fallback);
            $result[$symbol] = array(
                'info' => $entry,
                'symbol' => $symbol,
                'maker' => $this->safe_number($entry, 'maker_fee_rate'),
                'taker' => $this->safe_number($entry, 'taker_fee_rate'),
                'percentage' => true,
                'tierBased' => true,
            );
        }
        return $result;
    }

    public function create_order_request(array $market, string $type, string $side, mixed $amount, mixed $price = null, $params = array()): array {
        /**
         * @ignore
         * builds one order for the createOrders operation, returning the compact $signable $row next to the structured body $entry
         * @param {array} $market the $market the order targets
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price to fulfill the order at, a $market order can carry one to act like a protective bound
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dict with the $signable $row and the body $entry
         */
        $triggerPrice = $this->safe_string_n($params, array( 'triggerPrice', 'stopPrice', 'stopLossPrice', 'takeProfitPrice', 'trailingPercent', 'trailingAmount' ));
        $attached = $this->safe_value_n($params, array( 'stopLoss', 'takeProfit' ));
        if (($triggerPrice !== null) || ($attached !== null)) {
            throw new NotSupported($this->id . ' createOrder() does not support trigger or attached stop orders yet');
        }
        $symbol = $this->safe_symbol(null, $market);
        $isMarketOrder = ($type === 'market');
        $timeInForce = $this->safe_string_upper($params, 'timeInForce');
        $isPostOnlyTimeInForce = ($timeInForce === 'PO');
        $postOnly = false;
        $paramsOmitted = $params;
        list($postOnly, $paramsOmitted) = $this->handle_post_only($isMarketOrder, $isPostOnlyTimeInForce, $paramsOmitted);
        if ($isMarketOrder) {
            if (($timeInForce === 'GTC') || ($timeInForce === 'PO')) {
                throw new NotSupported($this->id . ' createOrder() does not support the ' . $timeInForce . ' timeInForce on market orders');
            }
            if ($timeInForce === null) {
                $timeInForce = 'IOC';
            }
        } else {
            if ($price === null) {
                throw new ArgumentsRequired($this->id . ' createOrder() requires a price argument for limit orders');
            }
            if (($timeInForce === null) || ($timeInForce === 'PO')) {
                $timeInForce = 'GTC';
            }
        }
        $tif = strtolower($timeInForce);
        $reduceOnly = $this->safe_bool($paramsOmitted, 'reduceOnly', false);
        $clientOrderId = $this->safe_string_2($paramsOmitted, 'clientOrderId', 'c');
        $paramsOmitted = $this->omit($paramsOmitted, array( 'timeInForce', 'reduceOnly', 'clientOrderId' ));
        $instrumentId = $this->parse_to_int($market['id']);
        $isBuy = ($side === 'buy');
        $quantity = $this->amount_to_precision($symbol, $amount);
        $priceString = null;
        if ($price !== null) {
            $priceString = $this->price_to_precision($symbol, $price);
        }
        $reduceOnlyValue = ($reduceOnly) ? true : null;
        // the signable row is positional - iid, buy, p, qty, tif, po, ro, c,
        // trigger - undefined entries are removed and later entries shift left,
        // the venue rebuilds the same compact array from the body to verify
        $row = array( $instrumentId, $isBuy, $priceString, $quantity, $tif, $postOnly, $reduceOnlyValue, $clientOrderId );
        $signable = $this->compact_signable($row);
        $entry = array(
            'iid' => $instrumentId,
            'buy' => $isBuy,
            'po' => $postOnly,
            'qty' => $quantity,
            'tif' => $tif,
        );
        if ($priceString !== null) {
            $entry['p'] = $priceString;
        }
        if ($reduceOnlyValue !== null) {
            $entry['ro'] = $reduceOnlyValue;
        }
        if ($clientOrderId !== null) {
            $entry['c'] = $clientOrderId;
        }
        return array(
            'signable' => $signable,
            'entry' => $entry,
            'params' => $paramsOmitted,
        );
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($symbol, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()) {
        /**
         * create a trade $order
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $symbol unified $symbol of the market to create an $order in
         * @param {string} $type 'market' or 'limit', a market $order executes like an immediate-or-cancel $order without a $price
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount how much you want to trade in units of the base currency
         * @param {float} [$price] the $price to fulfill the $order at, a market $order accepts one to act like a protective bound
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->timeInForce] 'GTC', 'IOC', 'FOK' or 'PO'
         * @param {bool} [$params->postOnly] true to place a maker only $order
         * @param {bool} [$params->reduceOnly] true to reduce an open position only
         * @param {string} [$params->clientOrderId] a client $order id, exactly 32 lowercase hex characters
         * @param {int} [$params->exp] expiry timestamp of the signed command in ms, bounds how long the gateway may hold the request
         * @return {array} an ~@link https://docs.ccxt.com/#/?id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $order = array(
            'symbol' => $symbol,
            'type' => $type,
            'side' => $side,
            'amount' => $amount,
            'price' => $price,
            'params' => $params,
        );
        $orders = Async\await($this->create_orders(array( $order ), $params));
        $first = $this->safe_dict($orders, 0, array());
        $firstStatus = $this->safe_string($first, 'status');
        if ($firstStatus === 'rejected') {
            $firstInfo = $this->safe_dict($first, 'info', array());
            $errorId = $this->safe_string($firstInfo, 'error');
            $feedback = $this->id . ' createOrder() rejected => ' . $this->json($firstInfo);
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $errorId, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $errorId, $feedback);
            throw new InvalidOrder($feedback);
        }
        $created = $this->safe_dict($orders, 0);
        return $created;
    }

    public function create_orders(array $orders, $params = array()): PromiseInterface {
        return Async\async(self::do_create_orders(...))($orders, $params);
    }

    private function do_create_orders(array $orders, $params = array()) {
        /**
         * create a list of trade $orders in one $signed batch
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {Array} $orders list of $orders to create, each object should contain the parameters required by createOrder, namely $symbol, $type, $side, $amount, $price and $params
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->exp] expiry timestamp of the $signed command in ms, bounds how long the gateway may hold the $request
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        $rows = array();
        $entries = array();
        $ordersMarkets = array();
        $ordersEntries = array();
        for ($i = 0; $i < count($orders); $i++) {
            $rawOrder = $orders[$i];
            $symbol = $this->safe_string($rawOrder, 'symbol');
            $market = $this->market($symbol);
            $type = $this->safe_string_lower($rawOrder, 'type');
            $side = $this->safe_string_lower($rawOrder, 'side');
            $amount = $this->safe_string($rawOrder, 'amount');
            $price = $this->safe_string($rawOrder, 'price');
            $orderParams = $this->safe_dict($rawOrder, 'params', array());
            $request = $this->create_order_request($market, $type, $side, $amount, $price, $orderParams);
            $rows[] = $request['signable'];
            $entries[] = $request['entry'];
            $ordersMarkets[] = $market;
            $ordersEntries[] = $request['entry'];
        }
        $signable = array( 'createOrders', $rows );
        $bodyOp = array(
            'type' => 'createOrders',
            'args' => $entries,
        );
        $signed = Async\await($this->sign_perps_op($signable, $bodyOp, $params));
        $response = Async\await($this->tradePostTradeOrders($signed));
        //
        //     [
        //         { "status": "ok", "oid": 1234567890, "coid": "aabbccdd..." }
        //     ]
        //
        $results = array();
        for ($i = 0; $i < count($response); $i++) {
            $ack = $this->safe_dict($response, $i, array());
            $marketInner = $ordersMarkets[$i];
            $echo = $this->safe_dict($ordersEntries, $i, array());
            $status = $this->safe_string($ack, 'status');
            $merged = $this->extend($echo, array(
                'oid' => $this->safe_integer($ack, 'oid'),
                'coid' => $this->safe_string_2($ack, 'coid', 'c'),
            ));
            if ($status === 'err') {
                $merged['status'] = 'rejected';
            } else {
                $merged['status'] = null;
            }
            $parsed = $this->parse_order($merged, $marketInner);
            $parsed['info'] = $ack;
            $results[] = $parsed;
        }
        return $results;
    }

    public function cancel_order(string $id, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_order(...))($id, $symbol, $params);
    }

    private function do_cancel_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * cancels an open order
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $id order $id
         * @param {string} [$symbol] not used by polymarket cancelOrder
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->clientOrderId] cancel by the client order $id instead of the exchange order $id
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~
         */
        $orders = Async\await($this->cancel_orders(array( $id ), $symbol, $params));
        $canceled = $this->safe_dict($orders, 0);
        return $canceled;
    }

    public function cancel_orders(array $ids, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_orders(...))($ids, $symbol, $params);
    }

    private function do_cancel_orders(array $ids, ?string $symbol = null, $params = array()) {
        /**
         * cancel multiple orders in one $signed batch
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string[]} $ids order $ids
         * @param {string} [$symbol] not used by polymarket cancelOrders
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string[]} [$params->clientOrderIds] cancel by client order $ids instead of the exchange order $ids
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        $clientOrderIds = $this->safe_list_2($params, 'clientOrderIds', 'clientOrderId');
        if ($clientOrderIds === null) {
            $clientOrderId = $this->safe_string($params, 'clientOrderId');
            if ($clientOrderId !== null) {
                $clientOrderIds = array( $clientOrderId );
            }
        }
        $paramsOmitted = $this->omit($params, array( 'clientOrderIds', 'clientOrderId' ));
        $signable = null;
        $bodyOp = null;
        $response = null;
        if ($clientOrderIds !== null) {
            $signable = array( 'cancelOrdersCOID', $clientOrderIds );
            $bodyOp = array(
                'type' => 'cancelOrdersCOID',
                'args' => $clientOrderIds,
            );
            $signed = Async\await($this->sign_perps_op($signable, $bodyOp, $paramsOmitted));
            $response = Async\await($this->tradeDeleteTradeOrdersCoid($signed));
        } else {
            $numericIds = array();
            for ($i = 0; $i < count($ids); $i++) {
                $numericIds[] = $this->parse_to_int($this->safe_string($ids, $i));
            }
            $signable = array( 'cancelOrders', $numericIds );
            $bodyOp = array(
                'type' => 'cancelOrders',
                'args' => $numericIds,
            );
            $signed = Async\await($this->sign_perps_op($signable, $bodyOp, $paramsOmitted));
            $response = Async\await($this->tradeDeleteTradeOrders($signed));
        }
        //
        //     [
        //         { "status": "ok", "oid": 1234567890, "ts": 1788546565789 }
        //     ]
        //
        $results = array();
        for ($i = 0; $i < count($response); $i++) {
            $ack = $this->safe_dict($response, $i, array());
            $status = $this->safe_string($ack, 'status');
            $unified = ($status === 'err') ? 'rejected' : 'canceled';
            $merged = array(
                'oid' => $this->safe_integer($ack, 'oid'),
                'coid' => $this->safe_string($ack, 'coid'),
                'uts' => $this->safe_integer($ack, 'ts'),
                'status' => $unified,
            );
            $parsed = $this->parse_order($merged);
            $parsed['info'] = $ack;
            $results[] = $parsed;
        }
        return $results;
    }

    public function cancel_all_orders(?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_all_orders(...))($symbol, $params);
    }

    private function do_cancel_all_orders(?string $symbol = null, $params = array()) {
        /**
         * cancel all open orders, optionally scoped to a single $market
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} [$symbol] unified $market $symbol, cancels the orders of every $market when omitted
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list with the raw acknowledgement of the venue
         */
        Async\await($this->load_markets());
        $args = array();
        $signableArgs = array();
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $instrumentId = $this->parse_to_int($market['id']);
            $args['iid'] = $instrumentId;
            $signableArgs = array( $instrumentId );
        }
        $signable = array( 'cancelAll', $signableArgs );
        $bodyOp = array(
            'type' => 'cancelAll',
            'args' => $args,
        );
        $signed = Async\await($this->sign_perps_op($signable, $bodyOp));
        $response = Async\await($this->tradeDeleteTradeOrdersAll($signed));
        //
        //     { "status": "ok" }
        //
        return array( $this->safe_order(array( 'info' => $response )) );
    }

    public function cancel_all_orders_after(?int $timeout, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_all_orders_after(...))($timeout, $params);
    }

    private function do_cancel_all_orders_after(?int $timeout, $params = array()) {
        /**
         * arms or clears a dead man's switch that cancels every open order once the $deadline passes
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {number} $timeout time in milliseconds, 0 represents cancel the timer, the venue requires at least 5 seconds
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the raw acknowledgement of the venue
         */
        Async\await($this->load_markets());
        $deadline = 0;
        if (($timeout !== null) && ($timeout > 0)) {
            $deadline = $this->sum($this->milliseconds(), $timeout);
        }
        $signable = array( 'autoCancel', array( $deadline ) );
        $bodyOp = array(
            'type' => 'autoCancel',
            'args' => array(
                'time' => $deadline,
            ),
        );
        $signed = Async\await($this->sign_perps_op($signable, $bodyOp));
        $response = Async\await($this->tradePatchTradeAutoCancel($signed));
        //
        //     { "status": "ok", "deadline": 1788546570789 }
        //
        return $response;
    }

    public function edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_edit_order(...))($id, $symbol, $type, $side, $amount, $price, $params);
    }

    private function do_edit_order(string $id, string $symbol, string $type, string $side, ?float $amount = null, ?float $price = null, $params = array()) {
        /**
         * edit a resting standalone gtc limit $order, only the $price and the total $quantity can change
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $id $order $id
         * @param {string} $symbol unified $symbol of the $market the $order was made in
         * @param {string} $type not used by polymarket editOrder
         * @param {string} $side not used by polymarket editOrder
         * @param {float} $amount the new total $order $quantity, it must exceed the already filled $quantity
         * @param {float} $price the new $order $price
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=$order-structure $order structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        if (($amount === null) || ($price === null)) {
            throw new ArgumentsRequired($this->id . ' editOrder() requires both the amount and the price arguments');
        }
        $orderId = $this->parse_to_int($id);
        $priceString = $this->price_to_precision($market['symbol'], $price);
        $quantity = $this->amount_to_precision($market['symbol'], $amount);
        $signable = array( 'modifyOrders', array( array( $orderId, $priceString, $quantity ) ) );
        $bodyOp = array(
            'type' => 'modifyOrders',
            'args' => array(
                array(
                    'oid' => $orderId,
                    'p' => $priceString,
                    'qty' => $quantity,
                ),
            ),
        );
        $signed = Async\await($this->sign_perps_op($signable, $bodyOp, $params));
        $response = Async\await($this->tradePatchTradeOrders($signed));
        //
        //     [
        //         {
        //             "status": "ok",
        //             "order": { "oid": 1, "iid": 1, "buy": true, "p": "7700", "qty": "0.001", "tif": "gtc", "po": false, "ro": false, "rest": "0.001", "fill": "0", "cts": 1788546565789, "uts": 1788546565789, "status": "open" }
        //         }
        //     ]
        //
        $first = $this->safe_dict($response, 0, array());
        $status = $this->safe_string($first, 'status');
        if ($status === 'err') {
            $merged = array(
                'oid' => $this->safe_integer($first, 'oid'),
                'coid' => $this->safe_string($first, 'coid'),
                'status' => 'rejected',
            );
            $rejected = $this->parse_order($merged, $market);
            $rejected['info'] = $first;
            return $rejected;
        }
        $order = $this->safe_dict($first, 'order', array());
        return $this->parse_order($order, $market);
    }

    public function parse_order_status(?string $status): ?string {
        $statuses = array(
            'accepted' => 'open',
            'open' => 'open',
            'partial' => 'open',
            'untriggered' => 'open',
            'armed' => 'open',
            'triggered' => 'open',
            'filled' => 'closed',
            'cancelled' => 'canceled',
            'auto_cancelled' => 'canceled',
            'fok_unfilled' => 'canceled',
            'ioc_no_fill' => 'canceled',
            'ioc_expired' => 'canceled',
            'stp_cancelled' => 'canceled',
            'reduce_only_expired' => 'canceled',
            'parent_cancelled' => 'canceled',
            'position_closed' => 'canceled',
            'position_flipped' => 'canceled',
            'reduce_only_invalid_at_trigger' => 'canceled',
            'order_expired' => 'expired',
            'expired' => 'expired',
            'post_only_rejected' => 'rejected',
            'zero_quantity' => 'rejected',
            'duplicate_order' => 'rejected',
            'order_not_found' => 'rejected',
            'reduce_only_invalid' => 'rejected',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_order(array $order, ?array $market = null): array {
        //
        // GET /v1/account/orders and /v1/account/open-orders use long names
        //
        //     {
        //         "order_id": 1234567890,
        //         "instrument_id": 1,
        //         "buy": true,
        //         "price": "7700.0",
        //         "quantity": "0.001",
        //         "tif": "gtc",
        //         "post_only": false,
        //         "ro": false,
        //         "resting_quantity": "0.001",
        //         "filled_quantity": "0",
        //         "status": "open",
        //         "created_timestamp": 1788546565789,
        //         "updated_timestamp": 1788546565789,
        //         "client_order_id": "aabbccddaabbccddaabbccddaabbccdd"
        //     }
        //
        // the modify acknowledgement and the ws orders channel use short names
        //
        //     {
        //         "oid": 1234567890,
        //         "iid": 1,
        //         "buy": true,
        //         "p": "7700.0",
        //         "qty": "0.001",
        //         "tif": "gtc",
        //         "po": false,
        //         "ro": false,
        //         "rest": "0.001",
        //         "fill": "0",
        //         "cts": 1788546565789,
        //         "uts": 1788546565789,
        //         "status": "open"
        //     }
        //
        $marketId = $this->safe_string_2($order, 'instrument_id', 'iid');
        $marketResolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer_2($order, 'created_timestamp', 'cts');
        $lastUpdateTimestamp = $this->safe_integer_2($order, 'updated_timestamp', 'uts');
        $isBuy = $this->safe_bool($order, 'buy');
        $side = null;
        if ($isBuy !== null) {
            $side = ($isBuy) ? 'buy' : 'sell';
        }
        $price = $this->omit_zero($this->safe_string_2($order, 'price', 'p'));
        $type = null;
        $tif = $this->safe_string($order, 'tif');
        if ($tif !== null) {
            $type = ($price === null) ? 'market' : 'limit';
        }
        $tpsl = $this->safe_dict($order, 'tpsl');
        $stopLossPrice = null;
        $takeProfitPrice = null;
        if ($tpsl !== null) {
            $kind = $this->safe_string($tpsl, 'kind');
            $triggerValue = $this->safe_string($tpsl, 'trp');
            if ($kind === 'sl') {
                $stopLossPrice = $triggerValue;
            } elseif ($kind === 'tp') {
                $takeProfitPrice = $triggerValue;
            }
        }
        return $this->safe_order(array(
            'info' => $order,
            'id' => $this->safe_string_2($order, 'order_id', 'oid'),
            'clientOrderId' => $this->safe_string_2($order, 'client_order_id', 'coid'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'lastUpdateTimestamp' => $lastUpdateTimestamp,
            'symbol' => $marketResolved['symbol'],
            'type' => $type,
            'timeInForce' => $this->safe_string_upper($order, 'tif'),
            'postOnly' => $this->safe_bool_2($order, 'post_only', 'po'),
            'reduceOnly' => $this->safe_bool($order, 'ro'),
            'side' => $side,
            'price' => $price,
            'triggerPrice' => null,
            'stopLossPrice' => $stopLossPrice,
            'takeProfitPrice' => $takeProfitPrice,
            'amount' => $this->safe_string_2($order, 'quantity', 'qty'),
            'cost' => null,
            'average' => null,
            'filled' => $this->safe_string_2($order, 'filled_quantity', 'fill'),
            'remaining' => $this->safe_string_2($order, 'resting_quantity', 'rest'),
            'status' => $this->parse_order_status($this->safe_string($order, 'status')),
            'fee' => null,
            'trades' => null,
        ), $marketResolved);
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * query for the $account equity, the free order $margin and the used initial $margin
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=balance-structure balance structure~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $response = Async\await($this->privateGetAccountPortfolio($params));
        //
        //     {
        //         "positions": [],
        //         "margin": {
        //             "total_account_value": "100.00",
        //             "available_order_margin": "90.00",
        //             "total_initial_margin": "10.00",
        //             "total_maintenance_margin": "5.00",
        //             "total_position_value": "50.00"
        //         },
        //         "withdrawable": "90.00",
        //         "in_liquidation": false,
        //         "timestamp": 1788546565789
        //     }
        //
        $margin = $this->safe_dict($response, 'margin', array());
        $timestamp = $this->safe_integer($response, 'timestamp');
        $result = array(
            'info' => $response,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
        );
        $account = $this->account();
        $account['total'] = $this->safe_string($margin, 'total_account_value');
        $account['free'] = $this->safe_string($margin, 'available_order_margin');
        $account['used'] = $this->safe_string($margin, 'total_initial_margin');
        // pUSD is the only collateral asset on the venue
        $result['PUSD'] = $account;
        return $this->safe_balance($result);
    }

    public function fetch_positions(?array $symbols = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_positions(...))($symbols, $params);
    }

    private function do_fetch_positions(?array $symbols = null, $params = array()) {
        /**
         * fetch all open $positions
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string[]} [$symbols] list of unified market $symbols
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=position-structure position structures~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $symbolsNormalized = $this->market_symbols($symbols);
        $response = Async\await($this->privateGetAccountPortfolio($params));
        $timestamp = $this->safe_integer($response, 'timestamp');
        $rows = $this->safe_list($response, 'positions', array());
        $positions = array();
        for ($i = 0; $i < count($rows); $i++) {
            // the wrapper timestamp flows into the parser through the merged input
            $extended = $this->extend($rows[$i], array( 'timestamp' => $timestamp ));
            $positions[] = $this->parse_position($extended);
        }
        return $this->filter_by_array_positions($positions, 'symbol', $symbolsNormalized);
    }

    public function fetch_position(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_position(...))($symbol, $params);
    }

    private function do_fetch_position(string $symbol, $params = array()) {
        /**
         * fetch data on a single open contract trade $position
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $symbol unified market $symbol of the market the $position is held in
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$position-structure $position structure~
         */
        $positions = Async\await($this->fetch_positions(array( $symbol ), $params));
        $position = $this->safe_dict($positions, 0);
        return $position;
    }

    public function parse_position(array $position, ?array $market = null): array {
        //
        //     {
        //         "instrument_id": 6,
        //         "symbol": "BTC-USD",
        //         "size": "-0.001",
        //         "entry_price": "79650.0",
        //         "leverage": 10,
        //         "cross": true,
        //         "initial_margin": "7.97",
        //         "maintenance_margin": "3.99",
        //         "position_value": "79.65",
        //         "liquidation_price": "85000.0",
        //         "unrealized_pnl": "-0.10",
        //         "return_on_equity": "-0.0125",
        //         "cumulative_funding": "0.01",
        //         "timestamp": 1788546565789
        //     }
        //
        $marketId = $this->safe_string($position, 'instrument_id');
        $marketResolved = $this->safe_market($marketId, $market);
        $size = $this->safe_string($position, 'size');
        $side = null;
        if ($size !== null) {
            $isLong = Precise::string_gt($size, '0');
            $side = ($isLong) ? 'long' : 'short';
        }
        $isCross = $this->safe_bool($position, 'cross');
        $marginMode = null;
        if ($isCross !== null) {
            $marginMode = ($isCross) ? 'cross' : 'isolated';
        }
        $timestamp = $this->safe_integer($position, 'timestamp');
        $roe = $this->safe_string($position, 'return_on_equity');
        $percentage = null;
        if ($roe !== null) {
            $percentage = $this->parse_number(Precise::string_mul($roe, '100'));
        }
        return $this->safe_position(array(
            'info' => $position,
            'id' => null,
            'symbol' => $marketResolved['symbol'],
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastUpdateTimestamp' => null,
            'initialMargin' => $this->safe_number($position, 'initial_margin'),
            'initialMarginPercentage' => null,
            'maintenanceMargin' => $this->safe_number($position, 'maintenance_margin'),
            'maintenanceMarginPercentage' => null,
            'entryPrice' => $this->safe_number($position, 'entry_price'),
            'notional' => $this->safe_number($position, 'position_value'),
            'leverage' => $this->safe_integer($position, 'leverage'),
            'unrealizedPnl' => $this->safe_number($position, 'unrealized_pnl'),
            'realizedPnl' => null,
            'contracts' => $this->parse_number(Precise::string_abs($size)),
            'contractSize' => $marketResolved['contractSize'],
            'marginRatio' => null,
            'liquidationPrice' => $this->parse_number($this->omit_zero($this->safe_string($position, 'liquidation_price'))),
            'markPrice' => null,
            'lastPrice' => null,
            'collateral' => $this->safe_number($position, 'initial_margin'),
            'marginMode' => $marginMode,
            'side' => $side,
            'percentage' => $percentage,
            'hedged' => false,
            'stopLossPrice' => null,
            'takeProfitPrice' => null,
        ));
    }

    public function fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_open_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all unfilled currently open orders
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] not sent to the venue, applied client-side
         * @param {int} [$limit] the maximum number of open order structures to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $request = array();
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $request['instrument_id'] = $market['id'];
        }
        $response = Async\await($this->privateGetAccountOpenOrders($this->extend($request, $params)));
        return $this->parse_orders($response, $market, $since, $limit);
    }

    public function fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_orders(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_orders(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the latest known snapshot of up to one hundred orders
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} [$symbol] unified $market $symbol of the $market orders were made in
         * @param {int} [$since] timestamp in ms of the earliest order
         * @param {int} [$limit] not sent to the venue, applied client-side
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest order
         * @param {string} [$params->clientOrderId] fetch the order with this client order id only
         * @return {Order[]} a list of ~@link https://docs.ccxt.com/#/?id=order-structure order structures~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $request = array();
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
            $request['instrument_id'] = $market['id'];
        }
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($params, 'until');
        $paramsOmitted = $params;
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $clientOrderId = $this->safe_string($paramsOmitted, 'clientOrderId');
        if ($clientOrderId !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'clientOrderId');
            $request['client_order_id'] = $clientOrderId;
        }
        $response = Async\await($this->privateGetAccountOrders($this->extend($request, $paramsOmitted)));
        return $this->parse_orders($response, $market, $since, $limit);
    }

    public function fetch_order(string $id, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order(...))($id, $symbol, $params);
    }

    private function do_fetch_order(string $id, ?string $symbol = null, $params = array()) {
        /**
         * fetches information on an order made by the user
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $id the order $id
         * @param {string} [$symbol] not used by polymarket fetchOrder
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} an ~@link https://docs.ccxt.com/#/?$id=order-structure order structure~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $request = array(
            'order_id' => $id,
        );
        $response = Async\await($this->privateGetAccountOrders($this->extend($request, $params)));
        // select the requested row explicitly in case the documented
        // order_id filter is ever ignored the way the tickers one is
        for ($i = 0; $i < count($response); $i++) {
            $row = $this->safe_dict($response, $i, array());
            $rowId = $this->safe_string($row, 'order_id');
            if ($rowId === $id) {
                return $this->parse_order($row, $market);
            }
        }
        throw new OrderNotFound($this->id . ' fetchOrder() could not find the order ' . $id);
    }

    public function fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_my_trades(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all trades made by the user
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} [$symbol] unified $market $symbol, the venue serves fills of every $market, filtered client-side
         * @param {int} [$since] timestamp in ms of the earliest trade
         * @param {int} [$limit] the maximum number of trade structures to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest trade
         * @param {string} [$params->cursor] opaque pagination cursor returned by the previous page
         * @return {Trade[]} a list of ~@link https://docs.ccxt.com/#/?id=trade-structure trade structures~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $market = null;
        if ($symbol !== null) {
            $market = $this->market($symbol);
        }
        $request = array();
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($params, 'until');
        $paramsOmitted = $params;
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $response = Async\await($this->privateGetAccountFills($this->extend($request, $paramsOmitted)));
        //
        //     {
        //         "data": [
        //             {
        //                 "trade_id": 3738280849593744,
        //                 "order_id": 1234567890,
        //                 "instrument_id": 6,
        //                 "side": "long",
        //                 "price": "79650.0",
        //                 "quantity": "0.001",
        //                 "taker": true,
        //                 "fee": "0.03",
        //                 "fee_asset": "USDC",
        //                 "previous_size": "0",
        //                 "previous_entry_price": "0",
        //                 "pnl": "0",
        //                 "liquidation": false,
        //                 "adl": false,
        //                 "timestamp": 1788546565789,
        //                 "hash": "0x"
        //             }
        //         ],
        //         "more": false,
        //         "cursor": "..."
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        return $this->parse_trades($data, $market, $since, $limit);
    }

    public function fetch_funding_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_funding_history(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_funding_history(?string $symbol = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch the funding payments paid and received on the open positions of the account
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} [$symbol] unified $market $symbol
         * @param {int} [$since] $timestamp in ms of the earliest funding payment
         * @param {int} [$limit] the maximum number of funding payment structures to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] $timestamp in ms of the latest funding payment
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=funding-history-structure funding history structures~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $market = null;
        $request = array();
        if ($symbol !== null) {
            $symbolMarket = $this->market($symbol);
            $market = $symbolMarket;
            $request['instrument_id'] = $symbolMarket['id'];
        }
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($params, 'until');
        $paramsOmitted = $params;
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $response = Async\await($this->privateGetAccountFunding($this->extend($request, $paramsOmitted)));
        //
        //     {
        //         "data": [
        //             {
        //                 "id": 123,
        //                 "instrument_id": 6,
        //                 "size": "0.001",
        //                 "funding_rate": "0.0000125",
        //                 "funding_asset": "USDC",
        //                 "funding": "-0.01",
        //                 "timestamp": 1788546565789
        //             }
        //         ],
        //         "more": false
        //     }
        //
        $data = $this->safe_list($response, 'data', array());
        $result = array();
        for ($i = 0; $i < count($data); $i++) {
            $entry = $data[$i];
            $marketId = $this->safe_string($entry, 'instrument_id');
            $timestamp = $this->safe_integer($entry, 'timestamp');
            $result[] = array(
                'info' => $entry,
                'symbol' => $this->safe_symbol($marketId, $market),
                'code' => $this->safe_currency_code($this->safe_string($entry, 'funding_asset')),
                'timestamp' => $timestamp,
                'datetime' => $this->iso8601($timestamp),
                'id' => $this->safe_string($entry, 'id'),
                'amount' => $this->safe_number($entry, 'funding'),
            );
        }
        return $this->filter_by_symbol_since_limit($result, $symbol, $since, $limit);
    }

    public function parse_transaction_status(?string $status): ?string {
        $statuses = array(
            'pending' => 'pending',
            'confirmed' => 'ok',
            'removed' => 'failed',
            'failed' => 'failed',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_transaction(array $transaction, ?array $currency = null): array {
        //
        // deposit row
        //
        //     {
        //         "hash": "0x...",
        //         "asset": "USDC",
        //         "amount": "100",
        //         "from": "0x...",
        //         "to": "0x...",
        //         "status": "confirmed",
        //         "confirmations": 10,
        //         "required_confirmations": 10,
        //         "created_timestamp": 1788546565789,
        //         "confirmed_timestamp": 1788546570789
        //     }
        //
        // withdrawal row
        //
        //     {
        //         "withdraw_id": 123,
        //         "asset": "USDC",
        //         "amount": "100",
        //         "to": "0x...",
        //         "fee": "0.1",
        //         "status": "pending",
        //         "hash": "0x",
        //         "confirmations": 0,
        //         "required_confirmations": 10,
        //         "created_timestamp": 1788546565789
        //     }
        //
        $withdrawId = $this->safe_string($transaction, 'withdraw_id');
        $type = ($withdrawId !== null) ? 'withdrawal' : 'deposit';
        $currencyId = $this->safe_string($transaction, 'asset');
        $code = $this->safe_currency_code($currencyId, $currency);
        $timestamp = $this->safe_integer($transaction, 'created_timestamp');
        $rawHash = $this->safe_string($transaction, 'hash');
        // the venue reports the literal 0x prefix while the transaction is unmined
        $txid = ($rawHash === '0x') ? null : $rawHash;
        $feeCost = $this->safe_string($transaction, 'fee');
        $fee = null;
        if ($feeCost !== null) {
            $fee = array(
                'cost' => $this->parse_number($feeCost),
                'currency' => $code,
            );
        }
        return array(
            'info' => $transaction,
            'id' => $withdrawId,
            'txid' => $txid,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'network' => null,
            'address' => null,
            'addressTo' => $this->safe_string($transaction, 'to'),
            'addressFrom' => $this->safe_string($transaction, 'from'),
            'tag' => null,
            'tagTo' => null,
            'tagFrom' => null,
            'type' => $type,
            'amount' => $this->safe_number($transaction, 'amount'),
            'currency' => $code,
            'status' => $this->parse_transaction_status($this->safe_string($transaction, 'status')),
            'updated' => $this->safe_integer($transaction, 'confirmed_timestamp'),
            'comment' => null,
            'internal' => false,
            'fee' => $fee,
        );
    }

    public function fetch_deposits(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_deposits(...))($code, $since, $limit, $params);
    }

    private function do_fetch_deposits(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetch all deposits made to the account
         *
         * @see https://docs.polymarket.com/perps/fund-your-account
         *
         * @param {string} [$code] unified $currency $code
         * @param {int} [$since] timestamp in ms of the earliest deposit
         * @param {int} [$limit] the maximum number of transaction structures to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest deposit
         * @return {array[]} a list of ~@link https://docs.ccxt.com/#/?id=transaction-structure transaction structures~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $request = array();
        if ($since !== null) {
            $request['start_timestamp'] = $since;
        }
        $until = $this->safe_integer($params, 'until');
        $paramsOmitted = $params;
        if ($until !== null) {
            $paramsOmitted = $this->omit($paramsOmitted, 'until');
            $request['end_timestamp'] = $until;
        }
        $response = Async\await($this->privateGetAccountDeposits($this->extend($request, $paramsOmitted)));
        $data = $this->safe_list($response, 'data', array());
        $currency = null;
        if ($code !== null) {
            $currency = $this->currency($code);
        }
        return $this->parse_transactions($data, $currency, $since, $limit);
    }

    public function fetch_withdrawals(?string $code = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_withdrawals(...))($code, $since, $limit, $params);
    }

