    public function withdraw(string $code, float $amount, string $address, $params = array()): PromiseInterface {
        return Async\async(self::do_withdraw(...))($code, $amount, $address, $params);
    }

    private function do_withdraw(string $code, float $amount, string $address, $params = array()) {
        /**
         * withdraw the $collateral asset to the polymarket wallet of the account, the $request is signed by the wallet key with the withdraw struct of the deposit $contract
         *
         * @see https://docs.polymarket.com/perps/fund-your-account
         *
         * @param {string} $code unified $currency $code
         * @param {float} $amount the $amount to withdraw
         * @param {string} $address the $address to withdraw to
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=$transaction-structure $transaction structure~
         */
        $this->check_required_credentials();
        Async\await($this->load_markets());
        $currency = $this->currency($code);
        $owner = $this->eth_get_address_from_private_key($this->privateKey);
        $collateral = $this->safe_dict($this->options, 'collateral', array());
        $tokenAddress = $this->safe_string($collateral, 'address');
        $decimals = $this->safe_string($collateral, 'decimals', '6');
        $precision = $this->parse_precision($decimals);
        // the signed amount is denominated using raw base units of the token
        $precised = $this->decimal_to_precision($this->number_to_string($amount), TRUNCATE, $this->parse_number($precision), TICK_SIZE);
        $baseUnits = Precise::string_div($precised, $precision);
        $ts = $this->seconds();
        $salt = $this->rand_number(9);
        $chainId = $this->safe_integer($this->options, 'chainId', 137);
        $contract = $this->safe_string($this->options, 'depositContract', '0xDCa4af75705dbB50f62437045afF9921947917d2');
        $domain = array(
            'name' => 'Polymarket',
            'version' => '1',
            'chainId' => $chainId,
            'verifyingContract' => $contract,
        );
        $messageTypes = array(
            'Withdraw' => array(
                array( 'name' => 'account', 'type' => 'address' ),
                array( 'name' => 'token', 'type' => 'address' ),
                array( 'name' => 'amount', 'type' => 'uint256' ),
                array( 'name' => 'fee', 'type' => 'uint256' ),
                array( 'name' => 'to', 'type' => 'address' ),
                array( 'name' => 'salt', 'type' => 'uint64' ),
                array( 'name' => 'ts', 'type' => 'uint64' ),
            ),
        );
        $message = array(
            'account' => $owner,
            'token' => $tokenAddress,
            'amount' => $this->parse_to_int($baseUnits),
            'fee' => 0,
            'to' => $address,
            'salt' => $salt,
            'ts' => $ts,
        );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $message);
        $signature = $this->sign_message($encoded, $this->privateKey);
        $request = array(
            'op' => array(
                'type' => 'withdraw',
                'args' => array(
                    'account' => $owner,
                    'token' => $tokenAddress,
                    'amount' => $baseUnits,
                    'to' => $address,
                ),
            ),
            'salt' => $salt,
            'sig' => $signature,
            'ts' => $ts,
        );
        $response = Async\await($this->tradePostAccountWithdraw($this->extend($request, $params)));
        //
        //     { "status": "ok", "withdraw_id": 123 }
        //
        // the ack status is the request discriminator, the accepted
        // withdrawal itself starts out pending
        $stripped = $this->omit($response, 'status');
        $transaction = $this->parse_transaction($stripped, $currency);
        $transaction['status'] = 'pending';
        return $transaction;
    }

    public function fetch_leverage(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_leverage(...))($symbol, $params);
    }

    private function do_fetch_leverage(string $symbol, $params = array()) {
        /**
         * fetch the leverage and the margin mode configured for a $market
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=leverage-structure leverage structure~
         */
        Async\await($this->load_markets());
        Async\await($this->load_proxy_credentials());
        $market = $this->market($symbol);
        $request = array(
            'instrument_id' => $market['id'],
        );
        $response = Async\await($this->privateGetAccountConfig($this->extend($request, $params)));
        //
        //     [ { "instrument_id": 1, "leverage": 10, "cross": true } ]
        //
        // select the requested row explicitly in case the documented
        // instrument_id filter is ever ignored the way the tickers one is
        for ($i = 0; $i < count($response); $i++) {
            $row = $this->safe_dict($response, $i, array());
            $rowId = $this->safe_string($row, 'instrument_id');
            if ($rowId === $market['id']) {
                return $this->parse_leverage($row, $market);
            }
        }
        throw new BadSymbol($this->id . ' fetchLeverage() could not find the configuration for ' . $symbol);
    }

    public function parse_leverage(array $leverage, ?array $market = null): array {
        $marketId = $this->safe_string($leverage, 'instrument_id');
        $marketResolved = $this->safe_market($marketId, $market);
        $isCross = $this->safe_bool($leverage, 'cross');
        $marginMode = null;
        if ($isCross !== null) {
            $marginMode = ($isCross) ? 'cross' : 'isolated';
        }
        $value = $this->safe_integer($leverage, 'leverage');
        return array(
            'info' => $leverage,
            'symbol' => $marketResolved['symbol'],
            'marginMode' => $marginMode,
            'longLeverage' => $value,
            'shortLeverage' => $value,
        );
    }

    public function fetch_margin_mode(string $symbol, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_margin_mode(...))($symbol, $params);
    }

    private function do_fetch_margin_mode(string $symbol, $params = array()) {
        /**
         * fetches the margin mode configured for a market
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $symbol unified market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=margin-mode-structure margin mode structure~
         */
        $leverage = Async\await($this->fetch_leverage($symbol, $params));
        return array(
            'info' => $this->safe_dict($leverage, 'info'),
            'symbol' => $this->safe_string($leverage, 'symbol'),
            'marginMode' => $this->safe_string($leverage, 'marginMode'),
        );
    }

    public function set_leverage(int $leverage, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_set_leverage(...))($leverage, $symbol, $params);
    }

    private function do_set_leverage(int $leverage, ?string $symbol = null, $params = array()) {
        /**
         * set the level of $leverage for a $market, optionally switching the margin mode at the same time
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {float} $leverage the rate of $leverage
         * @param {string} $symbol unified $market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->marginMode] 'cross' or 'isolated', the venue keeps the current mode when omitted is not supported - the default is cross
         * @return {array} the raw acknowledgement of the venue
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' setLeverage() requires a symbol argument');
        }
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $marginMode = null;
        $paramsOmitted = $params;
        list($marginMode, $paramsOmitted) = $this->handle_margin_mode_and_params('setLeverage', $paramsOmitted, 'cross');
        $isCross = ($marginMode !== 'isolated');
        $instrumentId = $this->parse_to_int($market['id']);
        $leverageInt = $this->parse_to_int($leverage);
        $signable = array( 'updateLeverage', array( $instrumentId, $leverageInt, $isCross ) );
        $bodyOp = array(
            'type' => 'updateLeverage',
            'args' => array(
                'cross' => $isCross,
                'iid' => $instrumentId,
                'lev' => $leverageInt,
            ),
        );
        $signed = Async\await($this->sign_perps_op($signable, $bodyOp));
        $response = Async\await($this->tradePatchTradeLeverage($signed));
        //
        //     { "status": "ok", "instrument_id": 1, "leverage": 10, "cross": true }
        //
        return $response;
    }

    public function set_margin_mode(string $marginMode, ?string $symbol = null, $params = array()): PromiseInterface {
        return Async\async(self::do_set_margin_mode(...))($marginMode, $symbol, $params);
    }

    private function do_set_margin_mode(string $marginMode, ?string $symbol = null, $params = array()) {
        /**
         * set the margin mode of a market, the venue updates the mode and the $leverage together
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $marginMode 'cross' or 'isolated'
         * @param {string} [$symbol] unified market $symbol
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {float} $params->leverage the rate of $leverage to set together with the mode
         * @return {array} the raw acknowledgement of the venue
         */
        if ($symbol === null) {
            throw new ArgumentsRequired($this->id . ' setMarginMode() requires a symbol argument');
        }
        $leverage = $this->safe_integer($params, 'leverage');
        if ($leverage === null) {
            throw new ArgumentsRequired($this->id . ' setMarginMode() requires a params.leverage argument, the venue updates the mode and the leverage in one operation');
        }
        $paramsOmitted = $this->omit($params, 'leverage');
        $request = array(
            'marginMode' => $marginMode,
        );
        $leverageInt = $this->parse_to_int($leverage);
        return Async\await($this->set_leverage($leverageInt, $symbol, $this->extend($request, $paramsOmitted)));
    }

    public function modify_margin_helper(string $symbol, mixed $amount, string $type, $params = array()): PromiseInterface {
        return Async\async(self::do_modify_margin_helper(...))($symbol, $amount, $type, $params);
    }

    private function do_modify_margin_helper(string $symbol, mixed $amount, string $type, $params = array()) {
        /**
         * @ignore
         * adds margin to an isolated position or removes some, the $amount is a $signed decimal in the $collateral asset
         * @param {string} $symbol unified $market $symbol
         * @param {float} $amount the $amount of margin to move
         * @param {string} $type 'add' or 'reduce'
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=add-margin-structure margin structure~
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $instrumentId = $this->parse_to_int($market['id']);
        $collateral = $this->safe_dict($this->options, 'collateral', array());
        $decimals = $this->safe_string($collateral, 'decimals', '6');
        $precision = $this->parse_precision($decimals);
        $amountString = $this->decimal_to_precision($this->number_to_string($amount), TRUNCATE, $this->parse_number($precision), TICK_SIZE);
        if ($type === 'reduce') {
            $amountString = '-' . $amountString;
        }
        $signable = array( 'updateMargin', array( $instrumentId, $amountString ) );
        $bodyOp = array(
            'type' => 'updateMargin',
            'args' => array(
                'amt' => $amountString,
                'iid' => $instrumentId,
            ),
        );
        $signed = Async\await($this->sign_perps_op($signable, $bodyOp));
        $response = Async\await($this->tradePatchTradeMargin($signed));
        //
        //     { "status": "ok" }
        //
        return array(
            'info' => $response,
            'symbol' => $market['symbol'],
            'type' => $type,
            'marginMode' => 'isolated',
            'amount' => $this->parse_number($amountString),
            'total' => null,
            'code' => $market['settle'],
            'status' => 'ok',
            'timestamp' => null,
            'datetime' => null,
        );
    }

    public function add_margin(string $symbol, float $amount, $params = array()): PromiseInterface {
        return Async\async(self::do_add_margin(...))($symbol, $amount, $params);
    }

    private function do_add_margin(string $symbol, float $amount, $params = array()) {
        /**
         * add margin to an isolated position
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $symbol unified market $symbol
         * @param {float} $amount amount of margin to add
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=add-margin-structure margin structure~
         */
        return Async\await($this->modify_margin_helper($symbol, $amount, 'add', $params));
    }

    public function reduce_margin(string $symbol, float $amount, $params = array()): PromiseInterface {
        return Async\async(self::do_reduce_margin(...))($symbol, $amount, $params);
    }

    private function do_reduce_margin(string $symbol, float $amount, $params = array()) {
        /**
         * remove margin from an isolated position
         *
         * @see https://docs.polymarket.com/perps/trading
         *
         * @param {string} $symbol unified market $symbol
         * @param {float} $amount the $amount of margin to remove
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/#/?id=reduce-margin-structure margin structure~
         */
        return Async\await($this->modify_margin_helper($symbol, $amount, 'reduce', $params));
    }

    public function hash_message(mixed $message) {
        return '0x' . $this->hash($message, 'keccak', 'hex');
    }

    public function sign_hash(mixed $hash, mixed $privateKey) {
        $signature = $this->ecdsa(mb_substr($hash, -64), mb_substr($privateKey, -64), 'secp256k1', null);
        $r = $signature['r'];
        $sVal = $signature['s'];
        $v = $this->int_to_base16($this->sum(27, $signature['v']));
        return '0x' . str_pad($r, 64, '0', STR_PAD_LEFT) . str_pad($sVal, 64, '0', STR_PAD_LEFT) . $v;
    }

    public function sign_message(mixed $message, mixed $privateKey) {
        return $this->sign_hash($this->hash_message($message), $privateKey);
    }

    public function create_proxy_credentials($params = array()): PromiseInterface {
        return Async\async(self::do_create_proxy_credentials(...))($params);
    }

    private function do_create_proxy_credentials($params = array()) {
        /**
         * provisions fresh trading session $credentials - generates a proxy keypair, registers it with an EIP-712 CreateProxy $message signed by the wallet key and caches the returned secret, the venue keeps the session valid for the requested $lifetime
         *
         * @see https://docs.polymarket.com/perps/authenticated-sessions
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the session $credentials, holding the proxy address, the proxy private key, the secret and the $expiry timestamp
         */
        $this->check_required_credentials();
        // the session key derives from an ecdsa signature under the wallet
        // key over a timestamped nonce - unpredictable without the wallet
        // secret and unique per provisioning, the paradex stark-key idiom
        $nonceMessage = 'polymarket-perps-proxy:' . (string) $this->milliseconds() . ':' . (string) $this->rand_number(9);
        $seedSignature = $this->sign_message($nonceMessage, $this->privateKey);
        $proxyPrivateKey = $this->hash($this->encode($seedSignature), 'keccak', 'hex');
        $proxyAddress = $this->eth_get_address_from_private_key($proxyPrivateKey);
        $owner = $this->eth_get_address_from_private_key($this->privateKey);
        $ts = $this->milliseconds();
        $lifetime = $this->safe_integer($this->options, 'proxyExpiry', 604800000);
        $expiry = $this->sum($ts, $lifetime);
        $salt = $this->rand_number(9);
        $chainId = $this->safe_integer($this->options, 'chainId', 137);
        $domain = array(
            'name' => 'Polymarket',
            'version' => '1',
            'chainId' => $chainId,
        );
        $messageTypes = array(
            'CreateProxy' => array(
                array( 'name' => 'addr', 'type' => 'address' ),
                array( 'name' => 'exp', 'type' => 'uint64' ),
                array( 'name' => 'salt', 'type' => 'uint64' ),
                array( 'name' => 'ts', 'type' => 'uint64' ),
            ),
        );
        $message = array(
            'addr' => $proxyAddress,
            'exp' => $expiry,
            'salt' => $salt,
            'ts' => $ts,
        );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $message);
        $signature = $this->sign_message($encoded, $this->privateKey);
        $request = array(
            'op' => array(
                'type' => 'createProxy',
                'args' => array(
                    'expiry' => $expiry,
                    'owner' => $owner,
                    'proxy' => $proxyAddress,
                ),
            ),
            'salt' => $salt,
            'sig' => $signature,
            'ts' => $ts,
        );
        $response = Async\await($this->tradePostAccountProxy($this->extend($request, $params)));
        //
        //     { "secret": "..." }
        //
        $credentials = array(
            'proxy' => $proxyAddress,
            'privateKey' => $proxyPrivateKey,
            'secret' => $this->safe_string($response, 'secret'),
            'expires' => $expiry,
        );
        $this->options['proxyCredentials'] = $credentials;
        return $credentials;
    }

    public function load_proxy_credentials($params = array()): PromiseInterface {
        return Async\async(self::do_load_proxy_credentials(...))($params);
    }

    private function do_load_proxy_credentials($params = array()) {
        /**
         * @ignore
         * returns the cached trading session $credentials, provisioning fresh ones when none are cached or the cached session is close to its expiry
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} the session $credentials, holding the proxy address, the proxy private key, the secret and the expiry timestamp
         */
        $credentials = $this->safe_dict($this->options, 'proxyCredentials');
        if ($credentials !== null) {
            $expires = $this->safe_integer($credentials, 'expires');
            $margin = $this->safe_integer($this->options, 'proxyRefreshMargin', 3600000);
            if ($expires === null) {
                return $credentials;
            }
            $refreshAfter = $expires - $margin;
            if ($this->milliseconds() < $refreshAfter) {
                return $credentials;
            }
        }
        return Async\await($this->create_proxy_credentials($params));
    }

    public function sign_perps_op(array $signable, array $bodyOp, $params = array()): PromiseInterface {
        return Async\async(self::do_sign_perps_op(...))($signable, $bodyOp, $params);
    }

    private function do_sign_perps_op(array $signable, array $bodyOp, $params = array()) {
        /**
         * @ignore
         * signs a trading operation with the session proxy key - the compact $signable array is msgpack-$encoded and keccak-hashed, the hash is signed inside an EIP-712 Op struct and the structured operation travels next to the $signature
         * @param {any[]} $signable the compact positional operation array, null entries already removed
         * @param {array} $bodyOp the structured operation object transmitted to the venue
         * @return {array} the signed request body with the op, sig, $salt and $ts fields
         */
        $credentials = Async\await($this->load_proxy_credentials());
        $packed = $this->packb($signable);
        $dataHash = $this->hash_message($packed);
        $ts = $this->milliseconds();
        $salt = $this->rand_number(9);
        $chainId = $this->safe_integer($this->options, 'chainId', 137);
        $domain = array(
            'name' => 'Polymarket',
            'version' => '1',
            'chainId' => $chainId,
        );
        $messageTypes = array(
            'Op' => array(
                array( 'name' => 'data', 'type' => 'bytes32' ),
                array( 'name' => 'salt', 'type' => 'uint64' ),
                array( 'name' => 'ts', 'type' => 'uint64' ),
            ),
        );
        $message = array(
            'data' => $dataHash,
            'salt' => $salt,
            'ts' => $ts,
        );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $message);
        $proxyPrivateKey = $this->safe_string($credentials, 'privateKey');
        $signature = $this->sign_message($encoded, $proxyPrivateKey);
        $envelope = array(
            'op' => $bodyOp,
            'sig' => $signature,
            'salt' => $salt,
            'ts' => $ts,
        );
        // the optional command expiry travels next to the signature and is
        // not part of the signed payload
        $exp = $this->safe_integer($params, 'exp');
        if ($exp !== null) {
            $envelope['exp'] = $exp;
        }
        return $envelope;
    }

    public function compact_signable(array $row) {
        /**
         * @ignore
         * removes null entries from a positional signable array, later entries shift left exactly like the official sdk does before hashing
         * @param {any[]} $row the positional array to compact
         * @return {any[]} the compacted array
         */
        $result = array();
        for ($i = 0; $i < count($row); $i++) {
            if ($row[$i] !== null) {
                $result[] = $row[$i];
            }
        }
        return $result;
    }

    public function price_to_precision(?string $symbol, mixed $price): ?string {
        if ($price === null) {
            return null;
        }
        // the venue caps prices at five significant figures on top of the
        // per-instrument decimals, deliberately for any magnitude - a six
        // digit integer price coarsens to an effective step of ten
        $market = $this->market($symbol);
        $precision = $this->safe_dict($market, 'precision', array());
        $significant = $this->decimal_to_precision($price, ROUND, 5, SIGNIFICANT_DIGITS);
        $result = $this->decimal_to_precision($significant, ROUND, $precision['price'], TICK_SIZE);
        if ($result === '0') {
            throw new InvalidOrder($this->id . ' price of ' . $market['symbol'] . ' must be greater than minimum price precision of ' . $this->number_to_string($precision['price']));
        }
        return $result;
    }

    public function amount_to_precision(?string $symbol, mixed $amount): ?string {
        if ($amount === null) {
            return null;
        }
        // quantities carry the same five significant figures cap
        $market = $this->market($symbol);
        $precision = $this->safe_dict($market, 'precision', array());
        $significant = $this->decimal_to_precision($amount, TRUNCATE, 5, SIGNIFICANT_DIGITS);
        $result = $this->decimal_to_precision($significant, TRUNCATE, $precision['amount'], TICK_SIZE);
        if ($result === '0') {
            throw new InvalidOrder($this->id . ' amount of ' . $market['symbol'] . ' must be greater than minimum amount precision of ' . $this->number_to_string($precision['amount']));
        }
        return $result;
    }

    public function calculate_rate_limiter_cost(array $api, string $method, string $path, mixed $params, $config = array()) {
        if ($path === 'account/orders') {
            return (is_array($params) && array_key_exists('order_id' ?? '', $params)) ? 1 : 10;
        }
        if ($path === 'account/open-orders') {
            return (is_array($params) && array_key_exists('instrument_id' ?? '', $params)) ? 1 : 20;
        }
        if (($path === 'trade/orders') || ($path === 'trade/orders-coid')) {
            $op = $this->safe_dict($params, 'op', array());
            $args = $this->safe_list($op, 'args', array());
            return $this->sum(1, $this->parse_to_int(strlen($args) / 20));
        }
        if ($path === 'info/book') {
            $depth = $this->safe_integer($params, 'depth', 100);
            if ($depth <= 10) {
                return 2;
            } elseif ($depth <= 100) {
                return 5;
            } elseif ($depth <= 500) {
                return 10;
            }
            return 20;
        }
        return $this->safe_value($config, 'cost', 1);
    }

    public function sign(string $path, array $api = array('public'), string $method = 'GET', $params = array()): array {
        $apiType = $api[0];
        $baseUrl = $this->safe_string($this->urls['api'], $apiType, '');
        $implodedPath = $this->implode_params($path, $params);
        $url = $baseUrl . '/' . $implodedPath;
        $query = $this->omit($params, $this->extract_params($path));
        $headersResolved = array(
            'Accept' => 'application/json',
        );
        $bodyResolved = null;
        if ($apiType === 'trade') {
            // the params hold the signed operation envelope assembled by the
            // calling method, the signature authenticates so no headers apply
            $bodyResolved = $this->json($query);
            $headersResolved['Content-Type'] = 'application/json';
        } else {
            if ($method === 'GET') {
                $keys = is_array($query) ? array_keys($query) : array();
                $keysLength = count($keys);
                if ($keysLength > 0) {
                    $url = $baseUrl . '/' . $implodedPath . '?' . $this->urlencode($query);
                }
            }
            if ($apiType === 'private') {
                $credentials = $this->safe_dict($this->options, 'proxyCredentials', array());
                $headersResolved['POLYMARKET-PROXY'] = $this->safe_string($credentials, 'proxy');
                $headersResolved['POLYMARKET-SECRET'] = $this->safe_string($credentials, 'secret');
            }
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $bodyResolved, 'headers' => $headersResolved );
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, ?array $requestHeaders, ?string $requestBody) {
        if ($response === null) {
            return null;
        }
        //
        //     {
        //         "status": "err",
        //         "error": "invalid query parameters: missing field `interval`",
        //         "arts": 1788524547131,
        //         "ts": 1788524547131,
        //         "ref": "g-164de39df348d7"
        //     }
        //
        $source = $response;
        if ((gettype($response) === 'array' && array_keys($response) === array_keys(array_keys($response))) && ($code >= 400)) {
            // request-level failures of the batch trade endpoints arrive
            // wrapped into a single-element array of the same error shape
            $source = $this->safe_dict($response, 0, array());
        }
        $status = $this->safe_string($source, 'status');
        $error = $this->safe_string($source, 'error');
        if (($status === 'err') || ($error !== null)) {
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $error, $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $error, $feedback);
            if ($code === 400) {
                // an unmapped 400 is a permanent validation failure with
                // free-form wording, never retryable
                throw new BadRequest($feedback);
            }
            // an unmapped error on a 4xx or 5xx response falls through so the
            // http status fallback can apply a retryable classification, while
            // covering statuses the base table does not know
            $codeAsString = (string) $code;
            if (($code < 400) || !(is_array($this->httpExceptions) && array_key_exists($codeAsString ?? '', $this->httpExceptions))) {
                throw new ExchangeError($feedback);
            }
        }
        return null;
    }
}
